function stampSVG(id){const s=R.stations[id],lines=R.lines.filter(l=>l.stations.includes(id)),ink=lines[0].color,scene=STAMP_LANDMARK[id]||(window.RailDrive?RailDrive.stationScene(id,lines.map(l=>l.id)):'sea'),key=`stamp-${++stampSeq}`,ring=2*Math.PI*90,fs=Math.min(44,132/s.name.length),rs=Math.min(18,84/s.reading.length);
return `<svg class="stamp-art" viewBox="0 0 200 200" aria-hidden="true"><defs><clipPath id="${key}"><circle cx="100" cy="100" r="76"/></clipPath></defs><g transform="rotate(${s.name.charCodeAt(0)%7-3} 100 100)">${lines.map((l,i)=>`<circle cx="100" cy="100" r="90" fill="none" stroke="${l.color}" stroke-width="12" stroke-dasharray="${ring/lines.length} ${ring}" stroke-dashoffset="${-i*ring/lines.length}" transform="rotate(-90 100 100)"/>`).join('')}<circle cx="100" cy="100" r="78" fill="none" stroke="${ink}" stroke-width="3"/>
<text x="100" y="50" text-anchor="middle" font-size="${rs}" font-weight="800" fill="${ink}">${esc(s.reading)}</text><text x="100" y="${80+fs/2.8}" text-anchor="middle" font-size="${fs}" font-weight="900" fill="${ink}">${esc(s.name)}</text><g clip-path="url(#${key})"><g transform="translate(100 110) scale(.98) translate(-100 -35)">${STAMP_ART[scene](ink)}</g></g></g></svg>`;}
// The press (as in the mock-up): the stamp comes down from large to its place in 0.3s and lands at about 0.2s, the page gives, then sparks; drive.js pon() plays the stamp sound file on the landing and the キラーン with the sparks (loaded ahead while the pad waits).
function stampBurst(id){const colors=[...R.lines.filter(l=>l.stations.includes(id)).map(l=>l.color),'#f5a524'];return Array.from({length:12},(_,i)=>`<i class="stamp-spark${i%2?' star':''}" aria-hidden="true" style="--a:${i*30+8}deg;--d:${i%3?112:132}px;--c:${colors[i%colors.length]}"></i>`).join('');}
function stampDay(id){const d=state.stamps?.[id];if(d){const [,m,day]=d.split('-').map(Number);return `${m}がつ ${day}にち`;}return id===C.opened(state)[0]?'しゅっぱつの えき':'まえに きたよ';}
