function renderPeople(){const counts=C.stats(state),name=profiles.names[store.who]||'';$('who-now').textContent=name;$('who-now').style.setProperty('--who',COLORS[store.who]);$('stats').innerHTML=`<p>${Object.keys(C.KINDS).filter(k=>counts[k]).map(k=>`${esc(KIND_NAMES[k])} ${counts[k]}問`).join(' ／ ')||'まだ 答えていません'}<br>合計 ${C.total(state)}問（答え直しを含む）<br>${C.opened(state).length}駅・${state.edges.length}区間 開通<br>開通済みの区間を走った回数：${C.ridden(state)}回<br>未使用の開通回数：${C.credits(state)}駅分</p>`;$('kind-list').innerHTML=[...C.OPS,C.LOOK].map(op=>`<fieldset><legend>${OP_LABELS[op].join(' ')}</legend>${Object.keys(C.KINDS).filter(k=>C.KINDS[k]===op).map(k=>`<label><input type="checkbox" value="${k}"${state.kinds.includes(k)?' checked':''}${conflict?' disabled':''}> ${esc(KIND_NAMES[k])}</label>`).join('')}${op===C.LOOK?lookWay():''}</fieldset>`).join('');$('name-list').innerHTML=C.PROFILES.map(p=>`<label style="--who:${COLORS[p.id]}"><i aria-hidden="true"></i><input data-name="${p.id}" value="${esc(profiles.names[p.id])}" maxlength="10" autocomplete="off" aria-label="${p.id==='guest'?'ゲスト':'なまえ'+p.id.slice(1)}の なまえ"></label>`).join('');$('guest-clear').hidden=store.who!=='guest';$('rest-on').checked=rest.on;$('rest-play').innerHTML=C.REST_PLAY.map(m=>`<option value="${m}"${m===rest.play?' selected':''}>${m}分</option>`).join('');$('rest-len').innerHTML=C.REST_LEN.map(m=>`<option value="${m}"${m===rest.rest?' selected':''}>${m}分</option>`).join('');$('rest-now').textContent=`いま続けて遊んでいる時間：約${Math.floor(rest.used/REST_UNIT)}分`;$('guest-clear').disabled=$('kinds-all').disabled=$('kinds-first').disabled=conflict;}
// How パッと見 comes for this person: a button of its own (to keep watching), and how long the car stays.
function lookWay(){const off=conflict||!state.kinds.some(k=>C.KINDS[k]===C.LOOK)?' disabled':'';return `<div class="look-way"><label>出し方 <select id="look-button"${off}><option value="">区間の1問目だけ</option><option value="1"${state.lookButton?' selected':''}>ボタンでも えらべる（続けて できる）</option></select></label><label>見える時間 <select id="look-stay"${off}>${C.LOOK_STAYS.map((ms,i)=>`<option value="${ms}"${ms===(state.lookStay||LOOK_STAY)?' selected':''}>${ms/1000}秒${['（ふつう）','','（ゆっくり）'][i]}</option>`).join('')}</select></label></div>`;}
function applyLook(){if(conflict||!C.setLook(state,!!$('look-button').value,Number($('look-stay').value),Date.now())){renderPeople();return;}$('who-status').textContent='パッと見の 出し方を 保存しました。';entry='';render();renderPeople();}
function applyKinds(kinds){if(conflict||!C.setKinds(state,kinds,Date.now())){$('who-status').textContent='たしざん などの 計算を 1つ以上 えらんでください。';renderPeople();return;}$('who-status').textContent='計算の種類を 保存しました。';entry='';render();renderPeople();}
$('kind-list').onchange=e=>e.target.matches('select')?applyLook():applyKinds([...$('kind-list').querySelectorAll('input:checked')].map(i=>i.value));$('kinds-all').onclick=()=>applyKinds(Object.keys(C.KINDS));$('kinds-first').onclick=()=>applyKinds(C.FIRST_KINDS);
$('names-save').onclick=()=>{const next={...profiles,names:{...profiles.names}};for(const input of $('name-list').querySelectorAll('[data-name]'))if(!C.rename(next,input.dataset.name,input.value)){$('who-status').textContent='なまえは 1〜10文字で 入れてください。';return;}if(profilesBroken){$('who-status').textContent='なまえの記録が読み込めないため、保存できません。';return;}profiles=next;$('who-status').textContent=saveProfiles()?'なまえを 保存しました。':'なまえを 保存できませんでした。';renderBadge();renderPeople();};
$('guest-clear').onclick=()=>{if(conflict||store.who!=='guest'||!confirm('ゲストの記録（正解数・開通した駅・車両カード）を消して、玖波駅からはじめますか？'))return;if(!restart()){$('who-status').textContent='消す前の記録を残せないため、中止しました。';return;}$('who-status').textContent='ゲストの記録を 消しました。';renderPeople();};
// Starting over keeps this person's kinds (and how パッと見 comes) and one copy of the record before (for 取り消し). It begins a new life, so merging with another device never brings the old record back; taking the copy back makes its life the newest.
function restart(){const kinds=state.kinds,look=[!!state.lookButton,state.lookStay||LOOK_STAY];try{store.keepBeforeReset(JSON.stringify(state));}catch(e){return false;}state=C.freshRecord(store.who);C.newLife(state,Date.now());C.setKinds(state,kinds);C.setLook(state,...look);state.news=[];corrupt=false;entry='';selected=state.current;render();centerMap();return true;}
// だれが あそぶ？ comes up on every launch; from the header it can be closed to keep playing.
function renderBadge(){const name=profiles.names[store.who]||'';$('who-open').style.setProperty('--who',COLORS[store.who]||'#fff');$('who-name').textContent=name;$('who-open').querySelector('i').textContent=[...name][0]||'';$('who-open').setAttribute('aria-label',`${name}（あそぶ人を かえる）`);}
function openWho(){$('who-list').innerHTML=C.PROFILES.map(p=>{let got='はじめて';try{const rec=JSON.parse(localStorage.getItem(C.recordKey(p.id)));if(C.valid(rec)&&rec.version===3)got=`🚩 ${C.opened(rec).length}えき`;}catch(e){}return `<button data-who="${p.id}" style="--who:${COLORS[p.id]}"><i aria-hidden="true">${esc([...profiles.names[p.id]][0])}</i><b>${esc(profiles.names[p.id])}</b><small>${got}</small></button>`;}).join('');$('who-close').hidden=!store.who;$('who').showModal();}
function pickWho(id){if(!C.PROFILES.some(p=>p.id===id))return;load(id);$('who').close();setQuiz(false);renderBadge();render();centerMap();showReward();if(!showRest())showNews();}
$('who-list').onclick=e=>{const b=e.target.closest('[data-who]');if(b)pickWho(b.dataset.who);};$('who-open').onclick=openWho;$('who-close').onclick=()=>$('who').close();$('who').addEventListener('cancel',e=>{if(!store.who)e.preventDefault();});$('who').addEventListener('close',()=>showRest());
// のりかえ案内 (trying it out locally, 2026-09-28): after three sections in a row answered with the same button, suggest another button (the one unused longest) once, with このまま to stay. Counted only while the page is open, per person; nothing is saved. ?norikae=1 suggests it after every section, for trying it out.
const TRANSFER_AFTER=/[?&]norikae=1(&|$)/.test(location.search)?1:3;let streak={mode:null,n:0},usedAt={},sections=0,transferDue=false,transferTo=null;
function countSection(mode){usedAt[mode]=++sections;streak=streak.mode===mode?{mode,n:streak.n+1}:{mode,n:1};if(streak.n>=TRANSFER_AFTER&&C.modes(state).length>1)transferDue=true;}
function showTransfer(){if(!transferDue||state.pending||conflict||document.querySelector('dialog[open]'))return false;const n=streak.n;transferDue=false;streak={mode:null,n:0};transferTo=C.modes(state).filter(m=>m!==state.mode).sort((a,b)=>(usedAt[a]||0)-(usedAt[b]||0))[0];if(!transferTo)return false;const now=OP_LABELS[state.mode][1],to=OP_LABELS[transferTo][1];$('transfer-heading').innerHTML=`${esc(to)}せんに<br>のりかえて みよう！`;$('transfer-text').textContent=`${now}せんに ${n}かい つづけて のったね。`;$('transfer-go').textContent=`${OP_LABELS[transferTo][0]} ${to}せんに のりかえる`;$('transfer-stay').textContent=`このまま ${now}せん`;$('transfer').showModal();window.RailDrive?.norikae(`のりかえの ごあんない です。${to}せんに、のりかえて みよう！`);return true;}
function closeTransfer(go){if(go&&transferTo&&!conflict&&C.setMode(state,transferTo)){entry='';render();}transferTo=null;$('transfer').close();showNews();}
$('transfer-go').onclick=()=>closeTransfer(true);$('transfer-stay').onclick=()=>closeTransfer(false);$('transfer').addEventListener('cancel',e=>{e.preventDefault();closeTransfer(false);});
// きゅうけい (2026-09-29): after 30 minutes of play in a row (per person, set in おうちの方へ), the rest screen comes when a section ends and stays until the rest is over (15 minutes); a reload or another launch shows it again. A little note comes 5 minutes before. Time is counted between taps (core.js restTick) and kept apart from the record. ほかの 人に かわる lets someone else play; an adult can end the rest with a check sum. ?kyukei=1 makes a minute 2 seconds, for trying it out.
const REST_UNIT=/[?&]kyukei=1(&|$)/.test(location.search)?2000:60000;let rest=C.freshRest('guest'),restTimer=null,restAnswer=null;
function loadRest(who){rest=C.freshRest(who);try{const r=JSON.parse(localStorage.getItem(C.restKey(who)));if(C.validRest(r))rest=r;}catch(e){}C.restTick(rest,Date.now(),REST_UNIT);saveRest();renderRestNote();}
function saveRest(){if(!store.who)return;try{localStorage.setItem(C.restKey(store.who),JSON.stringify(rest));}catch(e){}}
function renderRestNote(){$('rest-note').hidden=!(store.who&&C.restSoon(rest,REST_UNIT));}
function restTap(){if(!store.who)return;C.restTick(rest,Date.now(),REST_UNIT);saveRest();renderRestNote();if($('rest').open)renderRest();}
document.addEventListener('pointerdown',restTap,true);document.addEventListener('keydown',restTap,true);
function renderRest(){const left=C.restLeft(rest,Date.now());$('rest-bar').style.width=`${left?Math.round((1-left/(rest.rest*REST_UNIT))*100):100}%`;$('rest-left').textContent=left?`あと ${Math.ceil(left/REST_UNIT)}ふん`:'やすめたね！ また しゅっぱつ できるよ';$('rest-go').hidden=!!left;}
function restAsk(){const a=12+Math.floor(Math.random()*8),b=3+Math.floor(Math.random()*7);restAnswer=a*b;$('rest-question').textContent=`${a} × ${b} =`;$('rest-answer').value='';}
// Only at the start of a section (the five answers of the last one are in), so a problem or drive is never cut off.
function showRest(){if(!store.who||conflict||state.pending||document.querySelector('dialog[open]'))return false;const now=Date.now();C.restTick(rest,now,REST_UNIT);const fresh=!rest.until&&C.paid(state)%5===0&&C.startRest(rest,now,REST_UNIT);saveRest();renderRestNote();if(!rest.until)return false;setQuiz(false);const stations=Object.values(state.stamps||{}).filter(d=>d===today()).length;$('rest-done').innerHTML=`${rest.n?`<span>こんかい せいかい <b>${rest.n}</b>もん</span>`:''}${stations?`<span>きょう あたらしい えき <b>${stations}</b>えき</span>`:''}`;restAsk();$('rest-status').textContent='';document.querySelector('.rest-adult').open=false;renderRest();clearInterval(restTimer);restTimer=setInterval(renderRest,1000);$('rest').showModal();if(fresh)window.RailDrive?.norikae('きゅうけいの ごあんない です。でんしゃも ひとやすみ。すこし やすもうね。');return true;}
function closeRest(){clearInterval(restTimer);restTimer=null;$('rest').close();}
function endRest(){C.endRest(rest,Date.now());saveRest();renderRestNote();closeRest();if(!showTransfer())showNews();}
$('rest-go').onclick=()=>{if(!C.restLeft(rest,Date.now()))endRest();};$('rest-who').onclick=()=>{closeRest();openWho();};$('rest').addEventListener('cancel',e=>e.preventDefault());
$('rest-unlock').onclick=()=>{if(!/^\d+$/.test($('rest-answer').value.trim())||Number($('rest-answer').value)!==restAnswer){$('rest-status').textContent='確認の答えがちがいます。';restAsk();return;}endRest();};
$('parents').querySelector('.rest-settings').onchange=()=>{C.setRest(rest,$('rest-on').checked,Number($('rest-play').value),Number($('rest-len').value),Date.now());saveRest();renderRestNote();renderPeople();};
// Newly turned-on kinds get a celebration once, then the first new button is chosen.
function showNews(){if(!store.who||!state.news?.length||state.pending||document.querySelector('dialog[open]'))return;$('news-list').innerHTML=state.news.map(k=>`<li><b>${OP_LABELS[C.KINDS[k]][0]}</b>${esc(KIND_NAMES[k])}</li>`).join('');$('news').showModal();window.RailDrive?.seikai();}
function closeNews(){const first=state.news?.[0];C.seeNews(state);if(first)C.setMode(state,C.KINDS[first]);entry='';$('news').close();render();}
$('news-close').onclick=closeNews;$('news').addEventListener('cancel',e=>{e.preventDefault();closeNews();});
$('app-version').textContent=document.querySelector('meta[name="app-version"]')?.content||'不明';
$('update-app').onclick=async()=>{
const button=$('update-app');button.disabled=true;$('update-status').textContent='最新版を確認しています…';
try{
const url=new URL('index.html',document.baseURI);url.searchParams.set('update',Date.now().toString());
const response=await fetch(url.href,{cache:'no-store'});
if(!response.ok)throw Error('通信エラー '+response.status);
const html=await response.text();
const version=new DOMParser().parseFromString(html,'text/html').querySelector('meta[name="app-version"]')?.content;
if(!version)throw Error('更新データを確認できませんでした');
$('update-status').textContent='最新版を開きます。記録はそのまま残ります。';
location.replace(url.href);
}catch(error){button.disabled=false;$('update-status').textContent='更新できませんでした：'+error.message+'。通信を確認して、もう一度お試しください。';}
};
let resetAnswer=null;
function resetQuiz(){const a=12+Math.floor(Math.random()*8),b=3+Math.floor(Math.random()*7);resetAnswer=a*b;$('reset-question').textContent=`${a} × ${b} =`;$('reset-answer').value='';let undo=false;try{undo=!!store.beforeReset();}catch(e){}$('reset-undo').hidden=!undo;$('reset-app').disabled=$('reset-undo').disabled=conflict;}
$('reset-app').onclick=()=>{if(conflict)return;if(Number($('reset-answer').value)!==resetAnswer||!/^\d+$/.test($('reset-answer').value.trim())){$('reset-status').textContent='確認の答えがちがいます。';resetQuiz();return;}if(!confirm(`${profiles.names[store.who]}の 正解数・開通した駅・車両カードを消して、玖波駅から最初にもどします。よろしいですか？`)){resetQuiz();return;}if(!restart()){$('reset-status').textContent='リセット前の記録を残せないため、リセットを中止しました。先にバックアップを保存してください。';return;}resetQuiz();$('reset-status').textContent='最初からに もどしました。';};
$('reset-undo').onclick=()=>{if(conflict)return;try{const data=store.beforeReset();if(!data)throw Error();C.upgradeCards(data);if(!confirm('リセット前の記録に戻しますか？ リセットのあとに進めた分は消えます。'))return;state=data;C.revive(state,Date.now());corrupt=false;entry='';selected=state.current;render();if(!conflict&&storageOK)store.dropBeforeReset();centerMap();$('parents').close();showReward();}catch(e){$('reset-status').textContent='リセット前の記録を読み込めませんでした。';}};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=store.backupName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('ファイルが大きすぎます。');let data=JSON.parse(await f.text());if(data?.version===1)data=C.migrate(data);if(data?.version===2){data=C.fromV2(data,profiles.device);if(data){C.setKinds(data,state.kinds);C.setLook(data,!!state.lookButton,state.lookStay||LOOK_STAY);data.news=[];}}if(!C.valid(data)||data.version!==3)throw Error('有効なバックアップではありません。');C.upgradeCards(data);if(!confirm(`${profiles.names[store.who]}の記録を、このバックアップの記録に置き換えますか？`))return;state=data;corrupt=false;conflict=false;lastSaved=store.read();entry='';selected=state.current;render();centerMap();$('parents').close();showReward();}catch(err){$('import-status').textContent='復元できませんでした。'+err.message;}finally{e.target.value='';}};
$('zoom-in').onclick=()=>zoom(.7);$('zoom-out').onclick=()=>zoom(1/.7);$('map-current').onclick=()=>centerMap();$('map-all').onclick=mapAll;
let normalCamera=null;
$('map-full').onclick=()=>{const world=document.querySelector('.world'),on=!world.classList.contains('map-expanded');if(on)normalCamera={...camera};world.classList.toggle('map-expanded',on);$('map-full').textContent=on?'もどす':'大きく見る';if(on)mapAll();else{camera={...normalCamera};normalCamera=null;camera.height=camera.width/mapAspect();updateCamera();}};
const pointers=new Map();let gesture=null,moved=false;
$('map').addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});$('map').setPointerCapture(e.pointerId);moved=false;gesture={x:e.clientX,y:e.clientY,camera:{...camera},distance:pointers.size===2?Math.hypot(...(()=>{const p=[...pointers.values()];return[p[0].x-p[1].x,p[0].y-p[1].y];})()):null};});
$('map').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(gesture.distance){zoom(gesture.distance/d);gesture.distance=d;moved=true;}return;}const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;camera.x=gesture.camera.x-dx*camera.width/$('map').clientWidth;camera.y=gesture.camera.y-dy*camera.height/$('map').clientHeight;updateCamera();});
$('map').addEventListener('pointerup',e=>{if(!moved){const node=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-station]');if(node)showSelection(node.dataset.station);}pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.station){e.preventDefault();showSelection(e.target.dataset.station);}});
$('map').addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();zoom(e.deltaY>0?1.08:.92);}},{passive:false});
function resizeMap(){if(document.querySelector('.world').classList.contains('map-expanded'))mapAll();else{const cy=camera.y+camera.height/2;camera.height=camera.width/mapAspect();camera.y=cy-camera.height/2;updateCamera();}}
window.addEventListener('resize',resizeMap);
if(window.visualViewport)window.visualViewport.addEventListener('resize',resizeMap);
new ResizeObserver(resizeMap).observe($('map-wrap'));
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||e.target.closest('#map,button,input,a'))return;if(e.key==='Enter'&&state.solved){e.preventDefault();$('next').click();}else if(/^\d$/.test(e.key)){e.preventDefault();key(e.key);}else if(e.key==='Backspace'){e.preventDefault();key('clear');}else if(e.key==='Enter'){e.preventDefault();key('submit');}});
$('legend').innerHTML=R.lines.map(l=>`<span><i style="--line:${l.fill||l.color}${l.casing?`;box-shadow:0 0 0 1.5px ${l.casing}`:''}"></i>${l.name}</span>`).join('');centerMap();render();openWho();
